const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([100.141422, 20.248364]);
  const date1_start = '2015-01-27';
  const date1_end = '2015-01-28';
  const date2_start = '2020-01-25';
  const date2_end = '2020-01-26';

  // Function to mask clouds, shadow, and snow for Landsat 8 SR
  function maskL8sr(image) {
    // Bits 3 (cloud shadow), 4 (snow), and 5 (cloud) are the ones to mask.
    const cloudShadowBitMask = (1 << 3);
    const snowBitMask = (1 << 4);
    const cloudsBitMask = (1 << 5);
    const qa = image.select('QA_PIXEL');
    // All flags should be set to zero, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
                   .and(qa.bitwiseAnd(snowBitMask).eq(0))
                   .and(qa.bitwiseAnd(cloudsBitMask).eq(0));
    return image.updateMask(mask);
  }

  // Function to fetch and process data for a given period
  async function getSedimentProxy(start_date, end_date, year_label) {
    let collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_SR')
      .filterBounds(point)
      .filterDate(start_date, end_date);

    // Check if collection is empty
    const size = await ee.Number(collection.size()).getInfo();
    if (size === 0) {
      console.log(`Image Collection ${year_label}: 0 images found.`);
      return { value: null, count: 0, size: 0, status: 'C1' };
    }

    const image = collection.map(maskL8sr).mosaic();

    // Use the Red band (B4) as a proxy for suspended sediment.
    // Higher reflectance values suggest more sediment.
    const data = image.select('B4').reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: point,
      scale: 30, // Landsat resolution
      maxPixels: 1e9
    });

    const value = await ee.Number(data.get('B4_mean')).getInfo();
    const count = await ee.Number(data.get('B4_count')).getInfo();

    return { value, count, size, status: 'OK' };
  }

  // 2. Data Acquisition & Processing
  const result_2015 = await getSedimentProxy(date1_start, date1_end, '2015');
  const result_2020 = await getSedimentProxy(date2_start, date2_end, '2020');

  // 3. Validation
  if (result_2015.status === 'C1' || result_2020.status === 'C1') {
    console.log("Evidence: No images found for one or both dates.");
    console.log("A: Yes");
    return;
  }

  console.log(`2015 Image Collection Size: ${result_2015.size}`);
  console.log(`2020 Image Collection Size: ${result_2020.size}`);

  if (result_2015.count === 0 || result_2020.count === 0) {
    console.log(`Valid Pixels 2015: ${result_2015.count}`);
    console.log(`Valid Pixels 2020: ${result_2020.count}`);
    console.log("Evidence: No valid (cloud-free) pixels at the location for one or both dates.");
    console.log("B: No");
    return;
  }

  const val_2015 = result_2015.value;
  const val_2020 = result_2020.value;

  if (val_2015 === null || val_2020 === null) {
      console.log(`2015 Red Reflectance: ${val_2015}`);
      console.log(`2020 Red Reflectance: ${val_2020}`);
      console.log("Evidence: Calculation failed, resulting in null values.");
      console.log("B: No");
      return;
  }

  // 4. Final Answer
  // The Red band values are scaled by 0.0000275 and have an offset of -0.2.
  // We compare the raw digital numbers (DN) which is sufficient.
  const scaled_val_2015 = val_2015 * 0.0000275 - 0.2;
  const scaled_val_2020 = val_2020 * 0.0000275 - 0.2;

  console.log(`2015 Red Reflectance (proxy): ${scaled_val_2015.toFixed(4)}`);
  console.log(`2020 Red Reflectance (proxy): ${scaled_val_2020.toFixed(4)}`);

  if (scaled_val_2015 > scaled_val_2020) {
    console.log("Evidence: Red band reflectance, a proxy for sediment, was higher in 2015.");
    console.log("A: Yes");
  } else {
    console.log("Evidence: Red band reflectance, a proxy for sediment, was not higher in 2015.");
    console.log("B: No");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
  console.error(e);
  console.log("D: If image, collection, or band names are incorrect, syntax or method error, wrong method, or memory issue, etc.");
});
